(function(E){ const x = E["sales-m2"] = E["sales-m2"] || {units:{}}; x.units["sales-2-1"] = {"grammar":{"id":"c-sales-2-1-g","level":"B1","course":"sales","unit":"sales-2-1","title":"Questions that qualify: Who supplies...? / Who do you buy from?","titleTr":"Doğru alıcıyı bulan sorular: Who supplies...? / Who do you buy from?","titleFa":"سؤال‌هایی که خریدار واقعی را نشان می‌دهند: Who supplies...? و Who do you buy from?","formsTable":{"headers":{"en":["who / what = subject (no do)","who / what = object (do / does)"],"tr":["who / what = özne (do yok)","who / what = nesne (do / does)"],"fa":["who / what فاعل است (بدون do)","who / what مفعول است (با do / does)"]},"rows":[["Who supplies your shops now?","Who do you buy from now?"],["What sells best in your stores?","What do your customers ask for?"],["Which size sells fastest?","Which sizes does your team choose?"]]},"wrong":"Who does supply your shops at the moment?","right":"Who supplies your shops at the moment?","blank":{"sentence":"Which sizes ___ best in your stores?","word":"sell","distractors":["does sell","selling"]},"wrong2":"Who you buy from now?","right2":"Who do you buy from now?","blank2":{"sentence":"How many stores ___ the group have in Germany?","word":"does","distractors":["do","is"]},"expParts":{"tryFrom":"blank","rule":[{"en":"who/what does the action? No do.","tr":"Eylemi who/what mı yapıyor? do yok.","fa":"who یا what کار را انجام می‌دهد؟ do نمی‌آید.","ex":"Who supplies your shops now?"},{"en":"who/what receives the action? Use do or does.","tr":"Eylem who/what'a mı yapılıyor? do ya da does kullan.","fa":"کار روی who یا what انجام می‌شود؟ do یا does بیاور.","ex":"Who do you buy from now?"},{"en":"Test: answer it. Answer first in the sentence? Drop do.","tr":"Test: cevapla. Cevap cümlenin başında mı? do'yu at.","fa":"آزمون: جوابش را بده. جواب اول جمله است؟ do را بردار.","ex":"A firm in Spain supplies them."},{"en":"Ask about volume, timing and who decides.","tr":"Miktarı, zamanlamayı ve kimin karar verdiğini sor.","fa":"درباره‌ی مقدار، زمان و تصمیم‌گیرنده بپرس.","ex":"Who decides on a new supplier?"}],"test":{"en":"Say the answer out loud. 'The owner decides' = Who decides? 'She buys from Spain' = Who does she buy from?","tr":"Cevabı yüksek sesle söyle. 'The owner decides' = Who decides? 'She buys from Spain' = Who does she buy from?","fa":"جواب را بلند بگو. «The owner decides» یعنی Who decides? و «She buys from Spain» یعنی Who does she buy from?"},"contrast":{"en":"Turkish and Persian put the question word in the same place in both kinds ('Kim tedarik ediyor?' / 'Kimden alıyorsunuz?'; «کی تأمین می‌کند؟» / «از کی می‌خرید؟»). English adds do only when who or what is the object.","tr":"Türkçede iki tür soruda da soru kelimesi aynı yerde durur: 'Ürünlerinizi kim tedarik ediyor?' ve 'Kimden alıyorsunuz?'. İngilizcede ise do yalnızca who ya da what nesne olduğunda gelir.","fa":"در فارسی کلمه‌ی پرسشی در هر دو نوع سؤال سر جایش می‌ماند: «چه کسی کالاهایتان را تأمین می‌کند؟» و «از چه کسی می‌خرید؟». در انگلیسی do فقط وقتی می‌آید که who یا what مفعول باشد."}},"errorWatch":[{"find":["who does supply","who does make","who does buy","what does sell","which does sell","what did happen","who did make","who does decide"],"fix":{"en":"When who or what does the action, drop does: 'Who supplies your shops?'","tr":"Eylemi who ya da what yapıyorsa does'u at: 'Who supplies your shops?'","fa":"وقتی who یا what کار را انجام می‌دهد، does را بردار: «Who supplies your shops?»"}}]},"b2":{"id":"c-sales-2-1-b2","level":"B2","track":"B2","course":"sales","unit":"sales-2-1","title":"Checking gently: Aren't only the large sizes in stock?","titleTr":"Nazikçe kontrol etmek: Aren't only the large sizes in stock?","titleFa":"بررسی نرم: Aren't only the large sizes in stock?","formsTable":{"headers":{"en":["Use","Negative question"],"tr":["Kullanım","Olumsuz soru"],"fa":["کاربرد","سؤال منفی"]},"rows":[["Check a fact gently","Aren't only the large sizes in stock?"],["Remind someone","Didn't you say the price included freight?"],["Suggest softly","Wouldn't samples be a better start?"]]},"wrong":"Isn't the large sizes the ones in stock?","right":"Aren't the large sizes the ones in stock?","blank":{"sentence":"___ samples be a better first step than a full order?","word":"Wouldn't","distractors":["Doesn't","Isn't"]},"wrong2":"Didn't you said the price includes freight?","right2":"Didn't you say the price includes freight?","blank2":{"sentence":"Didn't you ___ that only the large sizes are in stock?","word":"say","distractors":["said","saying"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"A negative question expects 'yes': use it to check gently.","tr":"Olumsuz soru 'evet' bekler: nazikçe teyit için kullan.","fa":"سؤال منفی منتظر «بله» است: برای بررسی ملایم از آن استفاده کن.","ex":"Aren't only the large sizes in stock?"},{"en":"Auxiliary + n't + subject; base verb after didn't.","tr":"Yardımcı fiil + n't + özne; didn't'ten sonra yalın fiil.","fa":"فعل کمکی + n't + فاعل؛ بعد از didn't فعل ساده.","ex":"Didn't you say the price included freight?"},{"en":"Match the auxiliary to the subject.","tr":"Yardımcı fiili özneye uydur.","fa":"فعل کمکی را با فاعل هماهنگ کن.","ex":"Aren't the cartons...? / Isn't the label...?"},{"en":"Wouldn't + subject + be: a soft suggestion.","tr":"Wouldn't + özne + be: yumuşak bir öneri.","fa":"Wouldn't + فاعل + be: یک پیشنهاد نرم.","ex":"Wouldn't samples be a better start?"}],"test":{"en":"Say the normal question first (Are the cartons...?), then add n't to the first word.","tr":"Önce normal soruyu söyle (Are the cartons...?), sonra ilk kelimeye n't ekle.","fa":"اول سؤال معمولی را بگو (Are the cartons...?)، بعد به کلمه‌ی اول n't اضافه کن."},"contrast":{"en":"Turkish adds 'değil mi' at the end ('Sadece büyük bedenler stokta, değil mi?') and Persian starts with «مگر», so the verb does not move. English puts auxiliary + n't at the front.","tr":"Türkçede sona 'değil mi' eklenir ('Sadece büyük bedenler stokta, değil mi?'); fiil yer değiştirmez. İngilizcede yardımcı fiil + n't başa gelir.","fa":"فارسی با «مگر» شروع می‌کند و فعل جابه‌جا نمی‌شود. انگلیسی فعل کمکی + n't را اول جمله می‌گذارد."}},"errorWatch":[{"find":["didn't you said","didn't he said","didn't she said","didn't you sent","didn't you told"],"fix":{"en":"After didn't, use the base verb: 'Didn't you say...?'","tr":"Didn't'ten sonra yalın fiil kullan: 'Didn't you say...?'","fa":"بعد از didn't فعل ساده بیاور: «Didn't you say...?»"}},{"find":["isn't the cartons","isn't the sizes","isn't the samples","doesn't the cartons"],"fix":{"en":"Match the auxiliary to a plural subject: 'Aren't the cartons...?', 'Don't the cartons...?'","tr":"Yardımcı fiili çoğul özneye uydur: 'Aren't the cartons...?', 'Don't the cartons...?'","fa":"فعل کمکی را با فاعل جمع هماهنگ کن: «Aren't the cartons...?»، «Don't the cartons...?»"}}],"useIn":{"en":"B2: in the email or at the stand, check one fact with a negative question (for example 'Didn't you mention a test in twelve stores?').","tr":"B2: e-postada ya da standda bir bilgiyi olumsuz soruyla kontrol et (örneğin 'Didn't you mention a test in twelve stores?').","fa":"مسیر B2: در ایمیل یا غرفه، یک واقعیت را با سؤال منفی بررسی کن (مثلاً «Didn't you mention a test in twelve stores?»)."},"exitItem":{"from":"sales-2-1","kind":"blank","prompt":"___ the small jars your best sellers last year?","options":["Weren't","Wasn't","Didn't"],"correct":0}},"vocab":{"id":"c-sales-2-1-v","level":"B1","category":"vocab","course":"sales","unit":"sales-2-1","goals":["career"],"title":{"en":"At the fair","tr":"Fuarda","fa":"در نمایشگاه"},"cards":[{"word":"stand","sentence":"Our stand is near the main entrance.","meaning":{"en":"A company's small space at a trade fair.","tr":"stant.","fa":"غرفه"}},{"word":"lead","sentence":"We counted every lead at the end of the day.","meaning":{"en":"A person or company that might buy.","tr":"potansiyel müşteri bağlantısı.","fa":"سرنخ فروش؛ مشتری احتمالی"}},{"word":"qualify","sentence":"Good questions qualify a lead in a few minutes.","meaning":{"en":"To find out if someone is a real buyer.","tr":"bir adayın gerçek alıcı olup olmadığını anlamak.","fa":"سنجیدن اینکه کسی خریدار واقعی است یا نه"}},{"word":"stock","sentence":"The chain might stock our jars in a few stores.","meaning":{"en":"To keep a product in a shop to sell it.","tr":"(bir ürünü) mağazada bulundurmak, satmak.","fa":"موجود داشتن و فروختن کالا در فروشگاه"}},{"word":"sample","sentence":"She asked for one sample of each size.","meaning":{"en":"One product sent so the buyer can test it.","tr":"numune.","fa":"نمونه"}},{"word":"follow up","sentence":"We followed up the next morning.","gap":"followed up","accept":["followed up","follow up"],"meaning":{"en":"To contact someone again after a first meeting.","tr":"takip etmek, yeniden iletişime geçmek.","fa":"پیگیری کردن"}},{"word":"hot lead","sentence":"A hot lead wants a price this week.","meaning":{"en":"A likely buyer who is ready to buy soon.","tr":"sıcak potansiyel müşteri","fa":"مشتری بالقوه‌ی جدی و آماده‌ی خرید"}},{"word":"distributor","sentence":"We need a distributor in Poland.","meaning":{"en":"A company that buys goods and sells them on to shops.","tr":"distribütör","fa":"توزیع‌کننده"}},{"word":"business card","sentence":"She gave me her business card.","meaning":{"en":"A small card with your name, job and contact details.","tr":"kartvizit.","fa":"کارت ویزیت"}},{"word":"product sheet","sentence":"Our product sheet fits on one page.","meaning":{"en":"A page that describes a product.","tr":"ürün bilgi föyü.","fa":"برگه‌ی معرفی محصول"}}]},"judge":{"id":"c-sales-2-1-j","course":"sales","unit":"sales-2-1","type":"judge","title":{"en":"Stand talk: real buyer?","tr":"Stant konuşması: gerçek alıcı mı?","fa":"گفت‌وگوی غرفه: خریدار واقعی؟"},"prompt":"Four things a seller says to a visitor at a food fair.","parts":["Asks about them","Qualifies","Next step"],"instruction":{"en":"Tap what each line does. The best line does all three.","tr":"Her satırın ne yaptığına dokun. En iyi satır üçünü de yapar.","fa":"روی کاری که هر خط می‌کند بزن. بهترین خط هر سه را دارد."},"items":[{"by":"New rep","answer":"Can I help you? This is our catalogue. We make very good jam.","present":[],"fix":{"en":"Easy to answer with 'No, thanks'. Ask about them: 'What do you sell in your shops?'","tr":"'No, thanks' demek çok kolay. Onlarla ilgili sor: 'What do you sell in your shops?'","fa":"خیلی راحت می‌شود گفت «No, thanks». از خودشان بپرس: «What do you sell in your shops?»"}},{"by":"Sales rep","answer":"What do you like about the fair this year?","present":["Asks about them"],"fix":{"en":"Friendly, but it tells you nothing about buying. Ask about supply: 'Who supplies your jam now?'","tr":"Sıcak ama satın alma hakkında bir şey söylemiyor. Tedariği sor: 'Who supplies your jam now?'","fa":"دوستانه است، ولی چیزی درباره‌ی خرید نمی‌گوید. از تأمین بپرس: «Who supplies your jam now?»"}},{"by":"Sales rep","answer":"Who supplies your jam now, and how much do you buy a month?","present":["Asks about them","Qualifies"],"fix":{"en":"Good questions. Now close the talk with a step: 'I'll send you a price sheet tomorrow.'","tr":"İyi sorular. Şimdi konuşmayı bir adımla kapat: 'I'll send you a price sheet tomorrow.'","fa":"سؤال‌های خوبی است. حالا با یک قدم تمامش کن: «I'll send you a price sheet tomorrow.»"}},{"by":"Good model","answer":"Who supplies your jam now, and how much do you buy a month? Thanks. I'll send you a price sheet tomorrow.","present":["Asks about them","Qualifies","Next step"],"fix":null}]},"speaking":{"id":"sales-2-1","course":"sales","unit":"sales-2-1","topic":{"en":"Two minutes at the stand","tr":"Standda iki dakika","fa":"دو دقیقه در غرفه"},"warmup":{"en":"Which trade fair matters most for your field? Who goes there?","tr":"Senin alanın için en önemli fuar hangisi? Oraya kimler gider?","fa":"مهم‌ترین نمایشگاه در حوزه‌ی کار تو کدام است؟ چه کسانی به آن می‌روند؟"},"questions":[{"en":"A visitor stops at your stand. Open with one question about their business.","tr":"Bir ziyaretçi standında duruyor. İşiyle ilgili bir soruyla başla.","fa":"یک بازدیدکننده جلوی غرفه‌ات می‌ایستد. با سؤالی درباره‌ی کارش شروع کن."},{"en":"Ask about need, volume, who decides and when. Use one subject question.","tr":"İhtiyaç, miktar, kimin karar verdiği ve zamanı sor. Bir özne sorusu kullan.","fa":"از نیاز، مقدار، تصمیم‌گیرنده و زمان بپرس. یک سؤال فاعلی به کار ببر."},{"en":"The visitor says: 'Send me something.' Agree one exact next step and a day.","tr":"Ziyaretçi diyor ki: 'Send me something.' Net bir sonraki adımda ve günde anlaş.","fa":"بازدیدکننده می‌گوید: «Send me something.» روی یک قدم مشخص و یک روز توافق کن."}],"followups":[{"en":"Say the note you would write on this visitor's card.","tr":"Bu ziyaretçinin kartına yazacağın notu söyle.","fa":"یادداشتی را که پشت کارت این بازدیدکننده می‌نویسی بگو."}],"expressions":[{"phrase":"What do you sell in your ...?","meaning":{"en":"Opens with a question about them.","tr":"Onlarla ilgili bir soruyla açar.","fa":"با سؤالی درباره‌ی خودشان شروع می‌کند."}},{"phrase":"Who decides on ...?","meaning":{"en":"Finds the decision maker.","tr":"Karar vereni bulur.","fa":"تصمیم‌گیرنده را پیدا می‌کند."}},{"phrase":"I'll send you ... by ...","meaning":{"en":"Sets a clear next step.","tr":"Net bir sonraki adım koyar.","fa":"قدم بعدی روشنی مشخص می‌کند."}}],"model":"Hello. What do you sell in your shops? Interesting. Who supplies your dried fruit at the moment? And how much do you buy a month? Who decides on a new supplier: you or your director? When do you plan next year's range? Good. I'll send you our price sheet and two samples by Wednesday. May I have your card, please?","selfCheck":[{"en":"I started with a question about them.","tr":"Onlarla ilgili bir soruyla başladım.","fa":"با سؤالی درباره‌ی خودشان شروع کردم."},{"en":"I checked need, volume, who decides and when.","tr":"İhtiyacı, miktarı, karar vereni ve zamanı kontrol ettim.","fa":"نیاز، مقدار، تصمیم‌گیرنده و زمان را بررسی کردم."},{"en":"I used do only when who or what was the object.","tr":"Do'yu yalnızca who ya da what nesne olduğunda kullandım.","fa":"do را فقط وقتی به کار بردم که who یا what مفعول بود."},{"en":"I agreed one next step with a day.","tr":"Bir sonraki adımda ve bir günde anlaştım.","fa":"روی یک قدم بعدی و یک روز توافق کردم."}]},"writing":{"id":"c-sales-2-1-w","course":"sales","unit":"sales-2-1","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your fair follow-up","tr":"Fuar sonrası takip e-postan","fa":"ایمیل پیگیری نمایشگاه تو"},"portfolio":null,"prompt":{"en":"Use a real contact, or this note from a card: 'Food fair, Dubai. Buyer for 12 shops. Buys almonds from Spain, late twice. 2 pallets a month. Wants price by Friday.' Write the follow-up email (60-80 words): where you met, what you heard, what you are sending, and one clear next step.","tr":"Gerçek bir kişi ya da şu kart notunu kullan: 'Food fair, Dubai. Buyer for 12 shops. Buys almonds from Spain, late twice. 2 pallets a month. Wants price by Friday.' Takip e-postasını yaz (60-80 kelime): nerede görüştüğünüz, ne duyduğun, ne gönderdiğin ve net bir sonraki adım.","fa":"از یک مخاطب واقعی یا این یادداشت پشت کارت استفاده کن: «Food fair, Dubai. Buyer for 12 shops. Buys almonds from Spain, late twice. 2 pallets a month. Wants price by Friday.» ایمیل پیگیری را بنویس (۶۰ تا ۸۰ کلمه): کجا همدیگر را دیدید، چه شنیدی، چه چیزی می‌فرستی و یک قدم بعدی روشن."},"model":"Dear Mr Lindqvist,\n\nIt was good to meet you at the food fair in Dubai. You told me that you buy two pallets of almonds a month for your 12 shops, and that your last two deliveries were late. As promised, I attach our price sheet. Who decides on a new supplier: you or your director? Could we talk for ten minutes on Monday?\n\nBest regards","frame":"Dear ___,\n\nIt was good to meet you at ___. You told me that ___. As promised, I attach ___. Who decides ___? Could we talk ___?\n\nBest regards","words":[{"word":"You told me"},{"word":"As promised"},{"word":"Who decides"}],"minWords":50,"minSentences":4,"rubric":["Task done: where you met, what you heard, what you send, a next step","Organised: the meeting first, the request last","Language: subject and object questions are correct","Tone: personal, based on what this buyer really said"],"rubricI18n":{"tr":["Görev: nerede görüşüldüğü, ne duyulduğu, ne gönderildiği, bir sonraki adım","Düzen: önce görüşme, en sonda istek","Dil: özne ve nesne soruları doğru","Üslup: kişisel, bu alıcının gerçekten söylediklerine dayalı"],"fa":["کامل بودن کار: محل دیدار، چیزی که شنیدی، چیزی که می‌فرستی، قدم بعدی","نظم: اول دیدار، آخر درخواست","زبان: سؤال‌های فاعلی و مفعولی درست‌اند","لحن: شخصی و بر پایه‌ی حرف‌های واقعی همین خریدار"]}},"exit":{"id":"c-sales-2-1-x","course":"sales","unit":"sales-2-1","type":"exit","items":[{"from":"sales-2-1","kind":"blank","prompt":"Who ___ the colours for your stores?","options":["choose","chooses","choosing"],"correct":1,"point":2},{"from":"sales-2-1","kind":"mcq","prompt":"Which question helps you qualify a lead?","options":["How many stores would sell this line?","Do you like our stand and our samples?","Did you have a good flight to the fair?"],"correct":0,"point":1},{"from":"sales-2-1","kind":"mcq","prompt":"What should you do with a business card at the fair?","options":["Keep it safe and sort it next month.","Write a note on it straight away.","Give it to the next visitor."],"correct":1,"point":1},{"from":"sales-1-3","kind":"mcq","prompt":"In a needs call, what should you ask before the end?","options":["Who else decides, and what happens next","How long the buyer has worked there","Whether the buyer likes your factory"],"correct":0},{"from":"sales-1-2","kind":"blank","prompt":"Do you know when the samples ___?","options":["will arrive","will they arrive","do arrive"],"correct":0},{"from":"sales-1-1","kind":"blank","prompt":"The jar is unbreakable, ___ it survives long journeys.","options":["which means","which mean","what means"],"correct":0}]},"explain":{"id":"c-sales-2-1-e","course":"sales","unit":"sales-2-1","type":"explain","level":"B1","title":{"en":"Trade fairs: find the real buyers","tr":"Fuarlar: gerçek alıcıları bul","fa":"نمایشگاه‌ها: خریدارهای واقعی را پیدا کن"},"objective":{"en":"In this lesson you will learn to talk to visitors at a trade fair, find out quickly who is a real buyer, and agree a next step.","tr":"Bu derste fuarda ziyaretçilerle konuşmayı, kimin gerçek alıcı olduğunu hızla anlamayı ve bir sonraki adımda anlaşmayı öğreneceksin.","fa":"در این درس یاد می‌گیری در نمایشگاه با بازدیدکننده‌ها حرف بزنی، زود بفهمی چه کسی خریدار واقعی است و روی قدم بعدی توافق کنی."},"hook":{"en":"A full stand is not a full order book. The money is in the follow-up.","tr":"Dolu bir stant, dolu bir sipariş defteri değildir. Para takipte kazanılır.","fa":"غرفه‌ی شلوغ لزوماً به معنی سفارش زیاد نیست. پول در پیگیری است."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Qualify in two minutes","tr":"İki dakikada ayırt et","fa":"در دو دقیقه خریدار جدی را پیدا کن"},"steps":[{"en":"Open with a question about them, not 'Can I help you?'.","tr":"'Can I help you?' ile değil, onlarla ilgili bir soruyla başla.","fa":"با سؤالی درباره‌ی خودشان شروع کن، نه «Can I help you?».","ex":"What do you sell in your shops?"},{"en":"Check four things: need, volume, who decides, when.","tr":"Dört şeyi kontrol et: ihtiyaç, miktar, kim karar veriyor, ne zaman.","fa":"چهار چیز را بررسی کن: نیاز، مقدار، چه کسی تصمیم می‌گیرد، کی.","ex":"Who decides on a new supplier?"},{"en":"Write notes on the back of the card straight away.","tr":"Notları hemen kartvizitin arkasına yaz.","fa":"یادداشت‌ها را همان موقع پشت کارت ویزیت بنویس.","ex":"Hot. 2 pallets a month. Wants price by Friday."},{"en":"Agree one next step, then follow up within two days.","tr":"Bir sonraki adımda anlaş, sonra iki gün içinde takip et.","fa":"روی یک قدم بعدی توافق کن و ظرف دو روز پیگیری کن.","ex":"I'll send the price sheet tomorrow."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Questions that qualify: Who supplies...? / Who do you buy from?","tr":"Doğru alıcıyı bulan sorular: Who supplies...? / Who do you buy from?","fa":"سؤال‌هایی که خریدار واقعی را نشان می‌دهند: Who supplies...? و Who do you buy from?"},"steps":[{"en":"who/what does the action? No do.","tr":"Eylemi who/what mı yapıyor? do yok.","fa":"who یا what کار را انجام می‌دهد؟ do نمی‌آید.","ex":"Who supplies your shops now?"},{"en":"who/what receives the action? Use do or does.","tr":"Eylem who/what'a mı yapılıyor? do ya da does kullan.","fa":"کار روی who یا what انجام می‌شود؟ do یا does بیاور.","ex":"Who do you buy from now?"},{"en":"Test: answer it. Answer first in the sentence? Drop do.","tr":"Test: cevapla. Cevap cümlenin başında mı? do'yu at.","fa":"آزمون: جوابش را بده. جواب اول جمله است؟ do را بردار.","ex":"A firm in Spain supplies them."},{"en":"Ask about volume, timing and who decides.","tr":"Miktarı, zamanlamayı ve kimin karar verdiğini sor.","fa":"درباره‌ی مقدار، زمان و تصمیم‌گیرنده بپرس.","ex":"Who decides on a new supplier?"}],"table":{"headers":{"en":["who / what = subject (no do)","who / what = object (do / does)"],"tr":["who / what = özne (do yok)","who / what = nesne (do / does)"],"fa":["who / what فاعل است (بدون do)","who / what مفعول است (با do / does)"]},"rows":[["Who supplies your shops now?","Who do you buy from now?"],["What sells best in your stores?","What do your customers ask for?"],["Which size sells fastest?","Which sizes does your team choose?"]]},"tip":{"en":"Turkish and Persian put the question word in the same place in both kinds ('Kim tedarik ediyor?' / 'Kimden alıyorsunuz?'; «کی تأمین می‌کند؟» / «از کی می‌خرید؟»). English adds do only when who or what is the object.","tr":"Türkçede iki tür soruda da soru kelimesi aynı yerde durur: 'Ürünlerinizi kim tedarik ediyor?' ve 'Kimden alıyorsunuz?'. İngilizcede ise do yalnızca who ya da what nesne olduğunda gelir.","fa":"در فارسی کلمه‌ی پرسشی در هر دو نوع سؤال سر جایش می‌ماند: «چه کسی کالاهایتان را تأمین می‌کند؟» و «از چه کسی می‌خرید؟». در انگلیسی do فقط وقتی می‌آید که who یا what مفعول باشد."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Before and after the fair","tr":"Fuardan önce ve sonra","fa":"قبل و بعد از نمایشگاه"},"body":{"en":"Write to your best prospects two weeks before: tell them your stand number and offer a time to meet. Plan who follows up before the fair starts. Answer hot leads first, and mention what they told you.","tr":"İki hafta önce en iyi potansiyel müşterilerine yaz: stant numaranı söyle ve görüşme saati öner. Takibi kimin yapacağını fuar başlamadan planla. Önce sıcak müşterilere cevap ver ve sana söylediklerinden bahset.","fa":"دو هفته قبل به بهترین مشتری‌های بالقوه‌ات بنویس: شماره‌ی غرفه را بگو و وقت ملاقات پیشنهاد کن. قبل از شروع نمایشگاه مشخص کن چه کسی پیگیری می‌کند. اول به مشتری‌های جدی جواب بده و به حرف‌هایی که زده‌اند اشاره کن."},"phrases":[{"phrase":"What do you sell in your ...?","meaning":{"en":"Opens with a question about them.","tr":"Onlarla ilgili bir soruyla açar.","fa":"با سؤالی درباره‌ی خودشان شروع می‌کند."}},{"phrase":"Who decides on ...?","meaning":{"en":"Finds the decision maker.","tr":"Karar vereni bulur.","fa":"تصمیم‌گیرنده را پیدا می‌کند."}},{"phrase":"I'll send you ... by ...","meaning":{"en":"Sets a clear next step.","tr":"Net bir sonraki adım koyar.","fa":"قدم بعدی روشنی مشخص می‌کند."}},{"phrase":"lead","meaning":{"en":"A person or company that might buy.","tr":"potansiyel müşteri bağlantısı.","fa":"سرنخ فروش؛ مشتری احتمالی"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a chat into a lead","tr":"Sohbeti potansiyel müşteriye çevir","fa":"گپ را به مشتری بالقوه تبدیل کن"},"item":"Thanks for visiting. Here's our catalogue. Have a good fair!","answer":"Who supplies your shops now? How many cartons do you buy a month? Good. I'll send you the price sheet tomorrow.","walk":[{"en":"A catalogue with no question teaches you nothing.","tr":"Sorusuz bir katalog sana hiçbir şey öğretmez.","fa":"کاتالوگ بدون سؤال چیزی به تو یاد نمی‌دهد."},{"en":"Ask about their supplier and volume: is this a real buyer?","tr":"Tedarikçisini ve miktarını sor: bu gerçek bir alıcı mı?","fa":"از تأمین‌کننده و مقدار بپرس: این خریدار واقعی است؟"},{"en":"Promise one thing, and name the day you will do it.","tr":"Tek bir şey için söz ver ve hangi gün yapacağını söyle.","fa":"یک چیز قول بده و بگو چه روزی انجامش می‌دهی."}]},"quick":{"prompt":"To qualify a lead, you check the need, the volume, who decides and ___.","options":["when they will buy","where they had lunch","how they found the stand"],"correct":0,"why":{"en":"when they will buy: a real buyer has a need, a size, a decision maker and a date.","tr":"when they will buy: gerçek bir alıcının ihtiyacı, miktarı, karar vereni ve tarihi vardır.","fa":"when they will buy: خریدار واقعی نیاز، مقدار، تصمیم‌گیرنده و تاریخ دارد."}},"remember":{"en":"Every card you bring home needs a note and a date.","tr":"Eve getirdiğin her kartın bir notu ve bir tarihi olmalı.","fa":"هر کارتی که با خودت می‌آوری باید یادداشت و تاریخ داشته باشد."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Checking gently: Aren't only the large sizes in stock?","tr":"Nazikçe kontrol etmek: Aren't only the large sizes in stock?","fa":"بررسی نرم: Aren't only the large sizes in stock?"},"steps":[{"en":"A negative question expects 'yes': use it to check gently.","tr":"Olumsuz soru 'evet' bekler: nazikçe teyit için kullan.","fa":"سؤال منفی منتظر «بله» است: برای بررسی ملایم از آن استفاده کن.","ex":"Aren't only the large sizes in stock?"},{"en":"Auxiliary + n't + subject; base verb after didn't.","tr":"Yardımcı fiil + n't + özne; didn't'ten sonra yalın fiil.","fa":"فعل کمکی + n't + فاعل؛ بعد از didn't فعل ساده.","ex":"Didn't you say the price included freight?"},{"en":"Match the auxiliary to the subject.","tr":"Yardımcı fiili özneye uydur.","fa":"فعل کمکی را با فاعل هماهنگ کن.","ex":"Aren't the cartons...? / Isn't the label...?"},{"en":"Wouldn't + subject + be: a soft suggestion.","tr":"Wouldn't + özne + be: yumuşak bir öneri.","fa":"Wouldn't + فاعل + be: یک پیشنهاد نرم.","ex":"Wouldn't samples be a better start?"}],"table":{"headers":{"en":["Use","Negative question"],"tr":["Kullanım","Olumsuz soru"],"fa":["کاربرد","سؤال منفی"]},"rows":[["Check a fact gently","Aren't only the large sizes in stock?"],["Remind someone","Didn't you say the price included freight?"],["Suggest softly","Wouldn't samples be a better start?"]]},"body":{"en":"B2: in the email or at the stand, check one fact with a negative question (for example 'Didn't you mention a test in twelve stores?').","tr":"B2: e-postada ya da standda bir bilgiyi olumsuz soruyla kontrol et (örneğin 'Didn't you mention a test in twelve stores?').","fa":"مسیر B2: در ایمیل یا غرفه، یک واقعیت را با سؤال منفی بررسی کن (مثلاً «Didn't you mention a test in twelve stores?»)."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
